'''
class subset:

    def __init__(self):

        self.parent = 0
        self.rank = 0
        self.ancestor = 0
        self.child = 0
        self.sibling = 0
        self.color = 0

# Structure to represent a query
# A query consists of (L,R) and we
# will process the queries offline 
# a/c to Tarjan's offline LCA algorithm
class Query:

    def __init__(self, L, R):

        self.L = L
        self.R = R

